content:
:root {
  --color-primary: #4f46e5;
  --color-primary-light: #6366f1;
  --color-primary-dark: #3730a3;
  --color-accent: #06b6d4;
  --color-success: #10b981;
  --color-success-bg: #ecfdf5;
  --color-success-border: #a7f3d0;
  --color-bg-app: #f1f5f9;
  --color-bg-card-front: #ffffff;
  --color-bg-card-back: #f8fafc;
  --color-text-main: #0f172a;
  --color-text-sub: #475569;
  --color-text-muted: #94a3b8;
  --color-border: #e2e8f0;
  --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.08), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
  --shadow-lg: 0 10px 25px -3px rgba(0, 0, 0, 0.1), 0 4px 10px -4px rgba(0, 0, 0, 0.06);
  --shadow-card: 0 20px 30px -10px rgba(79, 70, 229, 0.12), 0 8px 16px -6px rgba(0, 0, 0, 0.08);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --radius-full: 9999px;
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Hiragino Kaku Gothic ProN", "Yu Gothic", sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background: var(--color-bg-app);
  color: var(--color-text-main);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

#root {
  width: 100%;
}

/* アプリメインコンテナ */
.app-container {
  max-width: 680px;
  margin: 0 auto;
  padding: 24px 16px 40px;
  display: flex;
  flex-direction: column;
  gap: 20px;
  min-height: 100vh;
}

/* ヘッダー */
.header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 4px 0;
}

.title-area {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.title {
  font-size: 26px;
  font-weight: 800;
  color: var(--color-text-main);
  background: linear-gradient(135deg, var(--color-primary-dark), var(--color-primary-light));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  letter-spacing: -0.5px;
}

.subtitle {
  font-size: 13px;
  color: var(--color-text-muted);
  font-weight: 500;
}

/* 進捗バー */
.progress-section {
  background: #ffffff;
  padding: 14px 18px;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--color-border);
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.progress-text {
  display: flex;
  justify-content: space-between;
  font-size: 13px;
  font-weight: 600;
  color: var(--color-text-sub);
}

.progress-bar-bg {
  width: 100%;
  height: 8px;
  background-color: #f1f5f9;
  border-radius: var(--radius-full);
  overflow: hidden;
}

.progress-bar-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--color-accent), var(--color-success));
  border-radius: var(--radius-full);
  transition: width 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}

/* フィルタータブ */
.filter-tabs {
  display: flex;
  gap: 8px;
  background: #ffffff;
  padding: 6px;
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border);
  box-shadow: var(--shadow-sm);
}

.tab-btn {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 8px 12px;
  border: none;
  background: transparent;
  color: var(--color-text-sub);
  font-size: 13px;
  font-weight: 600;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all 0.2s ease;
}

.tab-btn:hover {
  background: #f8fafc;
  color: var(--color-text-main);
}

.tab-btn-active {
  background: var(--color-primary);
  color: #ffffff !important;
  box-shadow: 0 2px 6px rgba(79, 70, 229, 0.3);
}

.badge-count {
  font-size: 11px;
  padding: 2px 7px;
  border-radius: var(--radius-full);
  background-color: rgba(0, 0, 0, 0.08);
  font-weight: 700;
}

.tab-btn-active .badge-count {
  background-color: rgba(255, 255, 255, 0.25);
  color: #ffffff;
}

/* カードステージ */
.card-stage {
  display: flex;
  justify-content: center;
  align-items: center;
  width: 100%;
  min-height: 340px;
}

/* 3Dカードコンテナ */
.card-container {
  width: 100%;
  height: 340px;
  perspective: 1000px;
  cursor: pointer;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}

.card-inner {
  position: relative;
  width: 100%;
  height: 100%;
  transform-style: preserve-3d;
  transition: transform 0.6s cubic-bezier(0.34, 1.56, 0.64, 1);
  border-radius: var(--radius-lg);
}

.card-inner-flipped {
  transform: rotateY(180deg);
}

/* カード表・裏 共通 */
.card-face {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
  border-radius: var(--radius-lg);
  padding: 28px 24px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  align-items: center;
  box-shadow: var(--shadow-card);
  border: 1px solid rgba(226, 232, 240, 0.8);
  box-sizing: border-box;
}

/* カード表面 */
.card-front {
  background: var(--color-bg-card-front);
  background-image: radial-gradient(#e0e7ff 1px, transparent 1px);
  background-size: 20px 20px;
}

/* カード裏面 */
.card-back {
  background: var(--color-bg-card-back);
  transform: rotateY(180deg);
  border-color: #c7d2fe;
}

/* バッジと品詞 */
.card-category-badge {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--color-primary);
  background: #eef2ff;
  padding: 4px 12px;
  border-radius: var(--radius-full);
  align-self: center;
}

/* 単語と発音記号 */
.card-word {
  font-size: 38px;
  font-weight: 800;
  letter-spacing: -0.5px;
  color: var(--color-text-main);
  text-align: center;
  margin-top: 8px;
  line-height: 1.2;
}

.card-phonetic {
  font-size: 16px;
  color: var(--color-text-muted);
  font-family: "Lucida Sans", "Lucida Grande", sans-serif;
  margin-top: 4px;
}

/* 音声ボタン */
.sound-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: #f1f5f9;
  border: 1px solid var(--color-border);
  color: var(--color-primary);
  cursor: pointer;
  transition: all 0.2s ease;
  margin-top: 10px;
}

.sound-btn:hover {
  background: #e0e7ff;
  color: var(--color-primary-dark);
  transform: scale(1.08);
}

.sound-btn:active {
  transform: scale(0.95);
}

/* ヒント・案内テキスト */
.card-hint {
  font-size: 13px;
  color: var(--color-text-muted);
  text-align: center;
}

.flip-instruction {
  font-size: 12px;
  color: var(--color-text-muted);
  display: flex;
  align-items: center;
  gap: 4px;
}

/* 裏面: 意味と例文 */
.card-meaning {
  font-size: 26px;
  font-weight: 700;
  color: var(--color-primary-dark);
  text-align: center;
  margin: 10px 0 14px;
}

.card-example-box {
  width: 100%;
  background: #ffffff;
  border-radius: var(--radius-md);
  padding: 14px 16px;
  border-left: 4px solid var(--color-primary);
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 6px;
  text-align: left;
}

.example-en {
  font-size: 15px;
  font-weight: 600;
  color: var(--color-text-main);
  line-height: 1.4;
}

.example-ja {
  font-size: 13px;
  color: var(--color-text-sub);
  line-height: 1.4;
}

/* 操作コントロールバー */
.controls-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-top: 6px;
}

.nav-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: #ffffff;
  border: 1px solid var(--color-border);
  color: var(--color-text-main);
  box-shadow: var(--shadow-sm);
  cursor: pointer;
  transition: all 0.2s ease;
  flex-shrink: 0;
}

.nav-btn:hover:not(:disabled) {
  background: #f8fafc;
  border-color: #cbd5e1;
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.nav-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

/* アクションボタングループ */
.action-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  height: 44px;
  padding: 0 16px;
  font-size: 14px;
  font-weight: 600;
  border-radius: var(--radius-full);
  cursor: pointer;
  transition: all 0.2s ease;
  border: none;
}

.btn-master {
  background: #ffffff;
  color: var(--color-text-sub);
  border: 1.5px solid var(--color-border);
  flex: 1;
  max-width: 200px;
}

.btn-master:hover {
  border-color: var(--color-success);
  color: var(--color-success);
  background: var(--color-success-bg);
}

.btn-mastered {
  background: var(--color-success-bg);
  color: var(--color-success);
  border: 1.5px solid var(--color-success);
  flex: 1;
  max-width: 200px;
  font-weight: 700;
}

.btn-mastered:hover {
  background: #d1fae5;
}

.btn-shuffle {
  background: #ffffff;
  border: 1px solid var(--color-border);
  color: var(--color-text-sub);
  box-shadow: var(--shadow-sm);
  width: 44px;
  height: 44px;
  border-radius: 50%;
  padding: 0;
}

.btn-shuffle:hover {
  background: #f8fafc;
  color: var(--color-primary);
  transform: rotate(15deg);
}

/* 空状態のプレースホルダー */
.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  background: #ffffff;
  border-radius: var(--radius-lg);
  padding: 48px 24px;
  text-align: center;
  border: 2px dashed var(--color-border);
  color: var(--color-text-muted);
  width: 100%;
  min-height: 320px;
}

.empty-state h3 {
  font-size: 18px;
  font-weight: 700;
  color: var(--color-text-main);
}

/* モーダル */
.modal-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(15, 23, 42, 0.6);
  backdrop-filter: blur(4px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  z-index: 100;
  animation: fadeIn 0.2s ease-out;
}

.modal-content {
  background: #ffffff;
  width: 100%;
  max-width: 480px;
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow-lg);
  max-height: 90vh;
  overflow-y: auto;
  animation: slideUp 0.25s ease-out;
}

.modal-title {
  font-size: 20px;
  font-weight: 700;
  color: var(--color-text-main);
  margin-bottom: 20px;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 16px;
}

.form-label {
  font-size: 13px;
  font-weight: 600;
  color: var(--color-text-sub);
}

.form-input {
  width: 100%;
  padding: 10px 14px;
  font-size: 14px;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  outline: none;
  background: #f8fafc;
  color: var(--color-text-main);
  transition: border-color 0.2s, background-color 0.2s;
  box-sizing: border-box;
}

.form-input:focus {
  border-color: var(--color-primary);
  background-color: #ffffff;
  box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.15);
}

.modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: 12px;
  margin-top: 24px;
}

.btn-cancel {
  padding: 10px 18px;
  border-radius: var(--radius-md);
  background: #f1f5f9;
  border: none;
  font-size: 14px;
  font-weight: 600;
  color: var(--color-text-sub);
  cursor: pointer;
  transition: background 0.2s;
}

.btn-cancel:hover {
  background: #e2e8f0;
}

.btn-submit {
  padding: 10px 22px;
  border-radius: var(--radius-md);
  background: var(--color-primary);
  border: none;
  font-size: 14px;
  font-weight: 600;
  color: #ffffff;
  cursor: pointer;
  transition: background 0.2s;
}

.btn-submit:hover {
  background: var(--color-primary-dark);
}

/* アニメーション */
@keyframes fadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes slideUp {
  from {
    opacity: 0;
    transform: translateY(16px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* レスポンシブ調整 */
@media (max-width: 480px) {
  .app-container {
    padding: 16px 12px 32px;
    gap: 16px;
  }

  .title {
    font-size: 22px;
  }

  .card-stage,
  .card-container {
    height: 320px;
  }

  .card-face {
    padding: 20px 16px;
  }

  .card-word {
    font-size: 32px;
  }

  .card-meaning {
    font-size: 22px;
  }

  .example-en {
    font-size: 14px;
  }

  .example-ja {
    font-size: 12px;
  }

  .controls-bar {
    gap: 8px;
  }

  .nav-btn {
    width: 42px;
    height: 42px;
  }

  .action-btn {
    height: 42px;
    padding: 0 12px;
    font-size: 13px;
  }
}

export interface Flashcard {
  id: string;
  word: string;
  meaning: string;
  phonetic: string;
  partOfSpeech: string;
  exampleEn: string;
  exampleJa: string;
  isMastered: boolean;
}

export type FilterType = 'all' | 'unmastered' | 'mastered';

export interface FlashcardProps {
  card: Flashcard;
  isFlipped: boolean;
  onFlip: () => void;
  onToggleMastered: (id: string) => void;
  onPlayAudio: (text: string) => void;
}

import { FlashcardProps } from '../types';
import { Volume2, RotateCw } from 'lucide-react';

const Card = ({
  card,
  isFlipped,
  onFlip,
  onPlayAudio,
}: FlashcardProps) => {
  const handleAudioClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    e.stopPropagation();
    onPlayAudio?.(card.word);
  };

  const handleExampleAudioClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    e.stopPropagation();
    onPlayAudio?.(card.exampleEn);
  };

  return (
    <div
      className="card-container"
      onClick={onFlip}
      role="button"
      tabIndex={0}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          onFlip?.();
        }
      }}
      aria-label={`${card.word}のカード。押すと裏返ります`}
    >
      <div className={isFlipped ? 'card-inner card-inner-flipped' : 'card-inner'}>
        {/* カード表面 */}
        <div className="card-face card-front">
          <span className="card-category-badge">{card.partOfSpeech}</span>

          <div>
            <h2 className="card-word">{card.word}</h2>
            <div className="card-phonetic">{card.phonetic}</div>
            <button
              type="button"
              className="sound-btn"
              onClick={handleAudioClick}
              title="発音を聞く"
              aria-label={`${card.word}の発音を聞く`}
            >
              <Volume2 size={22} />
            </button>
          </div>

          <div className="flip-instruction">
            <RotateCw size={14} />
            <span>タップして意味を確認</span>
          </div>
        </div>

        {/* カード裏面 */}
        <div className="card-face card-back">
          <span className="card-category-badge">{card.partOfSpeech}</span>

          <div>
            <p className="card-meaning">{card.meaning}</p>
            <div className="card-example-box">
              <div
                style={{
                  display: 'flex',
                  justifyContent: 'space-between',
                  alignItems: 'flex-start',
                  gap: '8px',
                }}
              >
                <p className="example-en">{card.exampleEn}</p>
                <button
                  type="button"
                  style={{
                    background: 'none',
                    border: 'none',
                    color: 'var(--color-primary)',
                    cursor: 'pointer',
                    padding: '2px',
                    display: 'flex',
                    alignItems: 'center',
                    flexShrink: 0,
                  }}
                  onClick={handleExampleAudioClick}
                  title="例文を聞く"
                  aria-label="例文の英語音声を聞く"
                >
                  <Volume2 size={16} />
                </button>
              </div>
              <p className="example-ja">{card.exampleJa}</p>
            </div>
          </div>

          <div className="flip-instruction">
            <RotateCw size={14} />
            <span>タップして表面に戻る</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Card;

import { useState, useCallback, useMemo } from 'react';
import {
  ChevronLeft,
  ChevronRight,
  Shuffle,
  Check,
  Plus,
  RotateCcw,
  BookOpen,
} from 'lucide-react';
import { Flashcard, FilterType } from './types';
import { initialCards } from './data/cards';
import Card from './components/Card';
import './index.css';

interface FormState {
  word: string;
  meaning: string;
  phonetic: string;
  partOfSpeech: string;
  exampleEn: string;
  exampleJa: string;
}

const initialFormState: FormState = {
  word: '',
  meaning: '',
  phonetic: '',
  partOfSpeech: 'noun',
  exampleEn: '',
  exampleJa: '',
};

const App = () => {
  const [cards, setCards] = useState<Flashcard[]>(() => {
    try {
      const saved = localStorage.getItem('vocab_flashcards');
      if (saved) {
        const parsed = JSON.parse(saved);
        if (Array.isArray(parsed) && parsed.length > 0) {
          return parsed;
        }
      }
    } catch {
      // localStorageエラー時はデフォルト配列
    }
    return initialCards;
  });

  const [currentIndex, setCurrentIndex] = useState<number>(0);
  const [isFlipped, setIsFlipped] = useState<boolean>(false);
  const [filter, setFilter] = useState<FilterType>('all');
  const [isModalOpen, setIsModalOpen] = useState<boolean>(false);
  const [formData, setFormData] = useState<FormState>(initialFormState);

  // フィルタリングされたカード一覧
  const filteredCards = useMemo(() => {
    if (filter === 'mastered') {
      return cards.filter((c) => c.isMastered);
    }
    if (filter === 'unmastered') {
      return cards.filter((c) => !c.isMastered);
    }
    return cards;
  }, [cards, filter]);

  // 現在のカード
  const safeIndex = Math.min(currentIndex, Math.max(0, filteredCards.length - 1));
  const currentCard = filteredCards[safeIndex] ?? null;

  // カウント集計
  const totalCount = cards.length;
  const masteredCount = cards.filter((c) => c.isMastered).length;
  const unmasteredCount = totalCount - masteredCount;
  const progressPercent = totalCount > 0 ? Math.round((masteredCount / totalCount) * 100) : 0;

  // カードめくり
  const handleFlip = useCallback(() => {
    setIsFlipped((prev) => !prev);
  }, []);

  // 次へ
  const handleNext = useCallback(() => {
    if (filteredCards.length === 0) return;
    setIsFlipped(false);
    setCurrentIndex((prev) => (prev + 1 < filteredCards.length ? prev + 1 : 0));
  }, [filteredCards.length]);

  // 前へ
  const handlePrev = useCallback(() => {
    if (filteredCards.length === 0) return;
    setIsFlipped(false);
    setCurrentIndex((prev) => (prev - 1 >= 0 ? prev - 1 : filteredCards.length - 1));
  }, [filteredCards.length]);

  // 音声読み上げ
  const handlePlayAudio = useCallback((text: string) => {
    if (!('speechSynthesis' in window)) return;
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = 'en-US';
    utterance.rate = 0.9;
    window.speechSynthesis.speak(utterance);
  }, []);

  // 習得状態トグル
  const handleToggleMastered = useCallback(
    (id: string) => {
      setCards((prev) => {
        const updated = prev.map((c) =>
          c.id === id ? { ...c, isMastered: !c.isMastered } : c
        );
        try {
          localStorage.setItem('vocab_flashcards', JSON.stringify(updated));
        } catch {
          // ignore
        }
        return updated;
      });
    },
    []
  );

  // シャッフル
  const handleShuffle = useCallback(() => {
    setIsFlipped(false);
    setCards((prev) => {
      const shuffled = [...prev];
      for (let i = shuffled.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
      }
      return shuffled;
    });
    setCurrentIndex(0);
  }, []);

  // フィルタ変更
  const handleFilterChange = (newFilter: FilterType) => {
    setIsFlipped(false);
    setFilter(newFilter);
    setCurrentIndex(0);
  };

  // フォーム入力処理
  const handleInputChange = (
    e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>
  ) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  // 単語新規作成
  const handleSubmitCard = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.word.trim() || !formData.meaning.trim()) {
      return;
    }

    const newCard: Flashcard = {
      id: `custom-${Date.now()}`,
      word: formData.word.trim(),
      meaning: formData.meaning.trim(),
      phonetic: formData.phonetic.trim() || `/${formData.word.trim().toLowerCase()}/`,
      partOfSpeech: formData.partOfSpeech || 'noun',
      exampleEn: formData.exampleEn.trim() || `${formData.word.trim()} is used in daily life.`,
      exampleJa: formData.exampleJa.trim() || 'この単語は日常生活で使われます。',
      isMastered: false,
    };

    setCards((prev) => {
      const updated = [newCard, ...prev];
      try {
        localStorage.setItem('vocab_flashcards', JSON.stringify(updated));
      } catch {
        // ignore
      }
      return updated;
    });

    setFormData(initialFormState);
    setIsModalOpen(false);
    setCurrentIndex(0);
    setIsFlipped(false);
  };

  return (
    <div className="app-container">
      {/* ヘッダー */}
      <header className="header">
        <div className="title-area">
          <h1 className="title">FlashVocab 3D</h1>
          <p className="subtitle">押すとくるっと裏返る英単語フラッシュカード</p>
        </div>
        <button
          type="button"
          className="action-btn btn-master"
          style={{ maxWidth: '130px' }}
          onClick={() => setIsModalOpen(true)}
          aria-label="新しい単語を追加"
        >
          <Plus size={16} />
          <span>単語を追加</span>
        </button>
      </header>

      {/* 進捗セクション */}
      <section className="progress-section" aria-label="学習進捗">
        <div className="progress-text">
          <span>覚えた単語の進捗</span>
          <span>
            {masteredCount} / {totalCount} 語 ({progressPercent}%)
          </span>
        </div>
        <div className="progress-bar-bg">
          <div
            className="progress-bar-fill"
            style={{ width: `${progressPercent}%` }}
          />
        </div>
      </section>

      {/* フィルタータブ */}
      <nav className="filter-tabs" aria-label="表示フィルター">
        <button
          type="button"
          className={filter === 'all' ? 'tab-btn tab-btn-active' : 'tab-btn'}
          onClick={() => handleFilterChange('all')}
        >
          すべて
          <span className="badge-count">{totalCount}</span>
        </button>
        <button
          type="button"
          className={filter === 'unmastered' ? 'tab-btn tab-btn-active' : 'tab-btn'}
          onClick={() => handleFilterChange('unmastered')}
        >
          復習中
          <span className="badge-count">{unmasteredCount}</span>
        </button>
        <button
          type="button"
          className={filter === 'mastered' ? 'tab-btn tab-btn-active' : 'tab-btn'}
          onClick={() => handleFilterChange('mastered')}
        >
          覚えた
          <span className="badge-count">{masteredCount}</span>
        </button>
      </nav>

      {/* カードステージ */}
      <main className="card-stage">
        {filteredCards.length > 0 && currentCard ? (
          <Card
            card={currentCard}
            isFlipped={isFlipped}
            onFlip={handleFlip}
            onToggleMastered={handleToggleMastered}
            onPlayAudio={handlePlayAudio}
          />
        ) : (
          <div className="empty-state">
            <BookOpen size={48} strokeWidth={1.5} />
            <h3>該当するカードがありません</h3>
            <p>
              {filter === 'mastered'
                ? 'まだ覚えたカードがありません。「覚えた」ボタンを押して登録しましょう！'
                : 'すべて覚えました！おめでとうございます。'}
            </p>
            {filter !== 'all' && (
              <button
                type="button"
                className="action-btn btn-master"
                onClick={() => handleFilterChange('all')}
                style={{ marginTop: '8px' }}
              >
                すべての単語を表示
              </button>
            )}
          </div>
        )}
      </main>

      {/* コントロールバー */}
      {filteredCards.length > 0 && currentCard && (
        <section className="controls-bar" aria-label="カード操作">
          <button
            type="button"
            className="nav-btn"
            onClick={handlePrev}
            aria-label="前のカード"
            title="前へ"
          >
            <ChevronLeft size={24} />
          </button>

          <button
            type="button"
            className={
              currentCard.isMastered
                ? 'action-btn btn-mastered'
                : 'action-btn btn-master'
            }
            onClick={() => handleToggleMastered(currentCard.id)}
            aria-label={
              currentCard.isMastered ? '未習得に戻す' : '覚えたに登録'
            }
          >
            {currentCard.isMastered ? (
              <>
                <Check size={18} />
                <span>覚えた！</span>
              </>
            ) : (
              <>
                <RotateCcw size={16} />
                <span>覚えた</span>
              </>
            )}
          </button>

          <button
            type="button"
            className="action-btn btn-shuffle"
            onClick={handleShuffle}
            title="シャッフル"
            aria-label="カードをシャッフル"
          >
            <Shuffle size={18} />
          </button>

          <button
            type="button"
            className="nav-btn"
            onClick={handleNext}
            aria-label="次のカード"
            title="次へ"
          >
            <ChevronRight size={24} />
          </button>
        </section>
      )}

      {/* カード枚数ナビインジケータ */}
      {filteredCards.length > 0 && (
        <div
          style={{
            textAlign: 'center',
            fontSize: '13px',
            color: 'var(--color-text-muted)',
            fontWeight: 600,
          }}
        >
          {safeIndex + 1} / {filteredCards.length}
        </div>
      )}

      {/* 新規単語追加モーダル */}
      {isModalOpen && (
        <div
          className="modal-overlay"
          onClick={() => setIsModalOpen(false)}
          role="dialog"
          aria-modal="true"
        >
          <div
            className="modal-content"
            onClick={(e) => e.stopPropagation()}
          >
            <h2 className="modal-title">新しい英単語を追加</h2>
            <form onSubmit={handleSubmitCard}>
              <div className="form-group">
                <label className="form-label" htmlFor="input-word">
                  英単語 *
                </label>
                <input
                  id="input-word"
                  className="form-input"
                  name="word"
                  value={formData.word}
                  onChange={handleInputChange}
                  placeholder="例: persist"
                  required
                />
              </div>

              <div className="form-group">
                <label className="form-label" htmlFor="input-meaning">
                  日本語の意味 *
                </label>
                <input
                  id="input-meaning"
                  className="form-input"
                  name="meaning"
                  value={formData.meaning}
                  onChange={handleInputChange}
                  placeholder="例: やり通す、持続する"
                  required
                />
              </div>

              <div className="form-group">
                <label className="form-label" htmlFor="input-pos">
                  品詞
                </label>
                <select
                  id="input-pos"
                  className="form-input"
                  name="partOfSpeech"
                  value={formData.partOfSpeech}
                  onChange={handleInputChange}
                >
                  <option value="verb">verb (動詞)</option>
                  <option value="noun">noun (名詞)</option>
                  <option value="adjective">adjective (形容詞)</option>
                  <option value="adverb">adverb (副詞)</option>
                  <option value="idiom">idiom (熟語)</option>
                </select>
              </div>

              <div className="form-group">
                <label className="form-label" htmlFor="input-phonetic">
                  発音記号 (任意)
                </label>
                <input
                  id="input-phonetic"
                  className="form-input"
                  name="phonetic"
                  value={formData.phonetic}
                  onChange={handleInputChange}
                  placeholder="例: /pərˈsɪst/"
                />
              </div>

              <div className="form-group">
                <label className="form-label" htmlFor="input-exampleEn">
                  英語例文 (任意)
                </label>
                <input
                  id="input-exampleEn"
                  className="form-input"
                  name="exampleEn"
                  value={formData.exampleEn}
                  onChange={handleInputChange}
                  placeholder="例: If the pain persists, consult a doctor."
                />
              </div>

              <div className="form-group">
                <label className="form-label" htmlFor="input-exampleJa">
                  例文の日本語訳 (任意)
                </label>
                <input
                  id="input-exampleJa"
                  className="form-input"
                  name="exampleJa"
                  value={formData.exampleJa}
                  onChange={handleInputChange}
                  placeholder="例: 痛みが続く場合は医師にご相談ください。"
                />
              </div>

              <div className="modal-actions">
                <button
                  type="button"
                  className="btn-cancel"
                  onClick={() => setIsModalOpen(false)}
                >
                  キャンセル
                </button>
                <button type="submit" className="btn-submit">
                  追加する
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;
